import{_ as t,o as h,c as o,a3 as g}from"./chunks/framework.DX_KL3e0.js";const u=JSON.parse('{"title":"Xin nghỉ phép","description":"","frontmatter":{},"headers":[],"relativePath":"huong-dan/xin-nghi-phep.md","filePath":"huong-dan/xin-nghi-phep.md","lastUpdated":1783009205000}'),i={name:"huong-dan/xin-nghi-phep.md"};function r(a,n,e,s,l,c){return h(),o("div",null,[...n[0]||(n[0]=[g('<h1 id="xin-nghi-phep" tabindex="-1">Xin nghỉ phép <a class="header-anchor" href="#xin-nghi-phep" aria-label="Permalink to &quot;Xin nghỉ phép&quot;">​</a></h1><blockquote><p><strong>🎯 Mục tiêu:</strong> Tạo đơn xin nghỉ và theo dõi quỹ phép năm. <strong>👤 Ai làm được:</strong> Mọi nhân sự. · <strong>⏱️ Khoảng:</strong> ~2 phút.</p></blockquote><h2 id="cac-buoc" tabindex="-1">Các bước <a class="header-anchor" href="#cac-buoc" aria-label="Permalink to &quot;Các bước&quot;">​</a></h2><ol><li>Vào <strong>Dữ Liệu Chấm Công</strong> → <strong>Nghỉ Phép</strong> → bấm <strong>Tạo Nghỉ Phép</strong>.</li><li>Chọn <strong>loại phép</strong> — mỗi loại hiện mô tả, hình thức trả lương (công ty / BHXH / không lương), giới hạn ngày và phép năm còn lại.</li><li>Chọn <strong>hình thức nghỉ</strong>: <strong>Theo ngày</strong> (từ ngày → đến ngày) hoặc <strong>Theo giờ</strong> (ngày + giờ bắt đầu/kết thúc). Một số loại chỉ cho nghỉ trọn ngày. <ul><li>🆕 Nghỉ nửa ngày: ở <em>Theo giờ</em>, bấm nút <strong>Nghỉ buổi sáng</strong> hoặc <strong>Nghỉ buổi chiều</strong> để tự điền khung giờ theo cấu hình công ty (thường 0.5 ngày).</li></ul></li><li>Xem <strong>dòng xem trước</strong> số ngày công bị trừ (đã tự bỏ Chủ Nhật &amp; ngày lễ).</li><li>Nhập <strong>lý do</strong> → bấm <strong>Gửi đơn</strong>.</li></ol><h2 id="✅-ket-qua" tabindex="-1">✅ Kết quả <a class="header-anchor" href="#✅-ket-qua" aria-label="Permalink to &quot;✅ Kết quả&quot;">​</a></h2><p>Đơn vào danh sách <strong>Đơn nghỉ phép của tôi</strong> với trạng thái <strong>Chờ duyệt</strong>, gửi tới quản lý trực tiếp xét duyệt.</p><h2 id="💡-meo-luu-y" tabindex="-1">💡 Mẹo &amp; lưu ý <a class="header-anchor" href="#💡-meo-luu-y" aria-label="Permalink to &quot;💡 Mẹo &amp; lưu ý&quot;">​</a></h2><ul><li>Đơn <strong>chờ duyệt</strong> hủy được; đơn <strong>đã duyệt</strong> vẫn hủy được nếu ngày bắt đầu nằm ở tương lai.</li><li>Xem <strong>quỹ phép năm</strong> (còn lại / đã cộng / đã nghỉ) ngay phía trên; chọn năm ở góc phải.</li></ul><p><em>Chi tiết: <a href="/help/chuc-nang/cham-cong.html#_4-nghi-phep">Nghỉ phép</a></em></p>',9)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
